shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-dark: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c1b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16293b;
    --crimson: #8f2822;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  /* Strict Bilingual Visibility Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.78;
  }

  /* Highlight styling */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.18) 0%, rgba(184, 93, 25, 0.26) 100%);
    color: var(--ink);
    padding: 0.08em 0.25em;
    border-radius: 2px;
    font-weight: 600;
    border-bottom: 1.5px solid var(--accent);
  }

  /* Sticky Top Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background-color: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--ink);
    box-shadow: 0 2px 12px rgba(20, 20, 19, 0.04);
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0.65rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .masthead-brand {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    padding: 0.15rem 0.5rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
  }

  .lang-switcher {
    display: inline-flex;
    border: 1px solid var(--ink);
    background: var(--paper-card);
    border-radius: 2px;
    overflow: hidden;
    flex-shrink: 0;
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .editorial-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  /* Hero Header */
  .hero-header {
    border-bottom: 3px double var(--ink);
    padding-bottom: 2.25rem;
    margin-bottom: 2.75rem;
  }

  .kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--muted);
  }

  .kicker-badge {
    color: var(--crimson);
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
  }

  .kicker-badge::before {
    content: "";
    display: inline-block;
    width: 8px;
    height: 8px;
    background-color: var(--crimson);
  }

  .article-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.35rem;
    max-width: 980px;
  }

  :host([lang="en"]) .article-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .editorial-standfirst {
    font-family: var(--font-sans);
    font-size: 1.05rem;
    line-height: 1.65;
    color: var(--muted);
    max-width: 820px;
    padding-left: 1rem;
    border-left: 3px solid var(--accent);
    margin-bottom: 1.75rem;
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.1rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-authors {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }

  .byline-meta {
    font-family: var(--font-mono);
    font-size: 0.78rem;
  }

  /* Act I: Asymmetric Forensic Grid */
  .act-one-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(280px, 1fr);
    gap: 3rem;
    align-items: start;
    margin-bottom: 3.25rem;
  }

  .prose-column {
    min-width: 0;
  }

  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.5rem;
    text-align: left;
  }

  /* Lead paragraph styling (NO ::first-letter on Chinese) */
  .prose-p.lead-para {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.78;
    padding-bottom: 1.35rem;
    border-bottom: 1px solid var(--line);
    margin-bottom: 1.65rem;
  }

  /* Forensic Dossier Rail */
  .forensic-rail {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 4px solid var(--ink);
    padding: 1.5rem;
  }

  .rail-header {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    padding-bottom: 0.65rem;
    margin-bottom: 1.1rem;
    border-bottom: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .dossier-item {
    padding-bottom: 0.9rem;
    border-bottom: 1px dashed var(--line-strong);
  }

  .dossier-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .dossier-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--muted);
    margin-bottom: 0.25rem;
  }

  .dossier-value {
    font-family: var(--font-sans);
    font-size: 0.92rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.45;
  }

  .network-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-top: 0.45rem;
  }

  .net-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    background: var(--paper);
    border: 1px solid var(--ink);
    color: var(--ink);
  }

  .net-pill.flagged {
    background: var(--crimson);
    color: var(--paper);
    border-color: var(--crimson);
  }

  /* Bespoke SVG Exhibit Container */
  .exhibit-panel {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 2px solid var(--ink);
    padding: 2rem 1.75rem;
    margin: 2.75rem 0 3.25rem;
  }

  .exhibit-top {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .exhibit-title {
    font-family: var(--font-sans);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--ink);
  }

  .exhibit-tag {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line-strong);
    padding: 0.5rem;
  }

  .exhibit-caption {
    margin-top: 0.85rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Act II: The Legal Crux & Sherman Act */
  .act-two-section {
    max-width: 840px;
    margin: 0 auto 3.25rem;
  }

  .section-marker {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin-bottom: 1.5rem;
  }

  .section-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    background: var(--ink);
    color: var(--paper);
    padding: 0.2rem 0.55rem;
    letter-spacing: 0.08em;
  }

  .section-label {
    font-family: var(--font-sans);
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
  }

  .section-rule {
    flex: 1;
    height: 1px;
    background: var(--line-strong);
  }

  /* Statutory Charge Banner for p5 */
  .charge-banner {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.85rem 2rem;
    margin: 2rem 0;
    border-left: 5px solid var(--accent);
    position: relative;
  }

  .charge-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e39758;
    margin-bottom: 0.6rem;
  }

  .charge-quote {
    font-size: 1.35rem;
    font-weight: 600;
    line-height: 1.55;
    color: var(--paper);
  }

  :host([lang="en"]) .charge-quote {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  .silence-note {
    font-family: var(--font-sans);
    font-size: 0.98rem;
    font-weight: 600;
    color: var(--muted);
    background: var(--paper-card);
    border-left: 3px solid var(--ink);
    padding: 0.85rem 1.25rem;
    margin: 1.5rem 0;
  }

  /* Act III: Escalation Matrix & Press Freedom */
  .act-three-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.5fr) minmax(270px, 1fr);
    gap: 2.75rem;
    align-items: start;
    max-width: 1080px;
    margin: 0 auto 3rem;
    padding-top: 2.25rem;
    border-top: 1px solid var(--line-strong);
  }

  /* Derived Pull Quote Card */
  .derived-quote-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--crimson);
    padding: 1.5rem;
  }

  .dq-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--crimson);
    font-weight: 700;
    margin-bottom: 0.75rem;
  }

  .pull-quote .quote-text {
    font-size: 1.05rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.85rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
    border-top: 1px solid var(--line);
    padding-top: 0.6rem;
  }

  /* Escalation Pattern Cards */
  .escalation-strip {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin: 2.25rem 0;
  }

  .esc-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.2rem;
  }

  .esc-step {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--accent);
    text-transform: uppercase;
    margin-bottom: 0.4rem;
  }

  .esc-title {
    font-family: var(--font-sans);
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.4rem;
  }

  .esc-desc {
    font-family: var(--font-sans);
    font-size: 0.83rem;
    color: var(--muted);
    line-height: 1.55;
  }

  /* Corporate Ownership Disclosure Footer */
  .disclosure-footer {
    max-width: 840px;
    margin: 3rem auto 0;
    padding: 1.35rem 1.6rem;
    background: var(--paper-dark);
    border: 1px solid var(--line-strong);
    display: flex;
    align-items: baseline;
    gap: 1rem;
  }

  .disclosure-badge {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
    background: var(--paper);
    border: 1px solid var(--ink);
    padding: 0.2rem 0.5rem;
    flex-shrink: 0;
  }

  .disclosure-text {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    color: var(--muted);
    line-height: 1.6;
    margin-bottom: 0;
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 860px) {
    .act-one-grid,
    .act-three-grid,
    .escalation-strip {
      grid-template-columns: 1fr;
      gap: 2rem;
    }

    .editorial-shell {
      padding: 1.5rem 1.1rem 3.5rem;
    }

    .charge-banner {
      padding: 1.35rem 1.25rem;
    }

    .disclosure-footer {
      flex-direction: column;
      gap: 0.5rem;
    }
  }
